css:
* { box-sizing: border-box; }
#root * { text-transform: uppercase; }
button, a { touch-action: manipulation; }
.app { min-height: 100%; }
.screen { max-width: var(--app-width); margin: 0px auto; padding: 0 var(--app-gutter) calc(var(--space-6) + env(safe-area-inset-bottom)); }
.stack { display: flex; flex-direction: column; gap: var(--stack-gap); }
.stack--section { --stack-gap: var(--space-section); }
.btn { --btn-fill: var(--surface-card); --btn-edge: var(--border-rule); --btn-ink: var(--text-body); --btn-fill-hover: var(--surface-inset); --btn-edge-hover: var(--text-caption); display: inline-flex; align-items: center; justify-content: center; gap: var(--space-1h); min-height: var(--tap-min); padding: var(--space-2) var(--space-4); border: var(--bw-rule) solid var(--btn-edge); border-radius: var(--radius-sm); background: var(--btn-fill); color: var(--btn-ink); font-family: var(--font-display); font-size: var(--fs-ui); letter-spacing: var(--ls-label); line-height: var(--lh-compact); text-align: center; text-decoration: none; text-transform: uppercase; cursor: pointer; transition: transform var(--dur-fast) var(--ease-stamp),
    background-color var(--dur-fast) var(--ease-standard),
    border-color var(--dur-fast) var(--ease-standard); }
.btn--control { min-height: var(--control-min); padding: var(--space-1) var(--space-3); font-size: var(--fs-label); }
.btn__icon { flex: 0 0 auto; font-size: 1.15em; line-height: var(--lh-solid); translate: 0px -0.06em; transition: rotate var(--dur-fast) var(--ease-standard); }
.btn:active { transform: translate(var(--bw-heavy), var(--bw-heavy)); }
.btn:focus-visible { outline: var(--bw-heavy) solid var(--focus-ring); outline-offset: var(--bw-heavy); }
.btn:disabled, .btn[aria-disabled="true"] { opacity: var(--opacity-disabled); cursor: default; }
@media (prefers-reduced-motion: reduce) {
.btn, .btn__icon { transition: none; }
.btn:active { transform: none; }
}
@media (prefers-reduced-motion: reduce) {
* { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}
.flipback :is(.pill, .btn, .hlclip, .hlclip__frame, .hlclip__play, .flipback__potgShotwrap, .plink) { border-radius: 0px; }
@media (min-width: 740px) {
.screen { max-width: 960px; }
}
.pnext__page { padding-top: var(--space-4); }
.pnext__section { padding-top: var(--space-3h); }
.playernext .pnext__section { flex-flow: wrap; container-type: inline-size; }
.pnext__section > .pnext__slot { flex: 1 1 100%; min-width: 0px; }
.pnext__slot { margin-top: var(--space-3h); }
.pnext-pick { min-height: var(--space-12); padding: 0 var(--space-3h); border: var(--bw-heavy) solid var(--border-stamped); border-radius: 0px; background: var(--surface-card); color: var(--text-heading); font-family: var(--font-display); font-size: var(--fs-body); font-weight: var(--w-bold); letter-spacing: var(--ls-caps); line-height: var(--lh-solid); text-transform: uppercase; cursor: pointer; }
.pnext-pick:disabled { opacity: var(--opacity-disabled); cursor: default; }
.pnext-pick[aria-pressed="true"] { background: var(--text-body); color: var(--text-on-ink); }
.pnext-pick:focus-visible { outline: var(--bw-heavy) solid var(--focus-ring); outline-offset: var(--bw-heavy); }
.fchart__plot { position: relative; border: var(--bw-heavy) solid var(--border-stamped); background: var(--surface-card); }
.fchart__plot:focus-within { outline: var(--bw-heavy) solid var(--focus-ring); outline-offset: var(--space-1); }
.fchart__svg { display: block; width: 100%; height: auto; }
.fchart__grid { fill: none; stroke: var(--border-hairline); stroke-width: 1; }
.fchart__season { fill: none; stroke: var(--text-caption); stroke-width: 1.4; stroke-dasharray: 5, 4; }
.fchart__fill--good { fill: var(--field-mint); fill-opacity: 0.55; }
.fchart__fill--bad { fill: var(--award-line); fill-opacity: 0.5; }
.fchart__line { fill: none; stroke: var(--text-heading); stroke-width: 2.6; stroke-linejoin: round; stroke-linecap: round; }
.fchart__rug { fill: none; stroke: var(--clay); stroke-width: 2.6; }
.fchart__cursor { fill: none; stroke: var(--text-heading); stroke-width: 1.4; }
.fchart__dot { stroke: var(--text-heading); stroke-width: 2; }
.fchart__dot--best { fill: var(--field-mint); }
.fchart__dot--worst { fill: var(--award-line); }
.fchart__dot--cursor { fill: var(--surface-card); stroke-width: 2.4; }
.fchart__scale { position: absolute; inset: 0px; pointer-events: none; }
.fchart__tick { position: absolute; left: var(--space-1h); transform: translateY(-115%); color: var(--text-caption); font-family: var(--font-mono); font-size: var(--fs-cell); }
.fchart__scrub { position: absolute; inset: 0px; width: 100%; height: 100%; margin: 0px; opacity: 0; cursor: ew-resize; touch-action: pan-y; }
.fchart__months { position: relative; height: var(--space-5); margin-top: var(--space-1h); }
.fchart__month { position: absolute; top: 0px; color: var(--text-caption); font-family: var(--font-display); font-size: var(--fs-label); font-weight: var(--w-bold); letter-spacing: var(--ls-label); text-transform: uppercase; }
.fstretch__grid { display: grid; grid-template-columns: minmax(0, 1fr) repeat(var(--fcols, 4), 3rem); column-gap: var(--space-1h); align-items: center; }
.fstretch__head { padding: 0 var(--space-2) var(--space-1h); border-bottom: var(--bw-heavy) solid var(--border-stamped); color: var(--text-caption); font-family: var(--font-display); font-size: var(--fs-label); font-weight: var(--w-bold); letter-spacing: var(--ls-label); text-transform: uppercase; }
.fstretch__head > :not(:first-child), .fstretch__fig { text-align: right; }
.fstretch__row { display: block; width: 100%; padding: var(--space-3) var(--space-2); border-top: 0px; border-right: 0px; border-left: 0px; border-image: initial; border-bottom: var(--bw-hair) solid var(--border-hairline); background: transparent; color: inherit; font: inherit; text-align: left; }
.fstretch__row--pick { cursor: pointer; }
.fstretch__row--pick:focus-visible { outline: var(--bw-heavy) solid var(--focus-ring); outline-offset: calc(var(--space-1) * -1); }
.fstretch__name { display: flex; flex-direction: column; min-width: 0px; }
.fstretch__title { color: var(--text-heading); font-family: var(--font-display); font-size: var(--fs-h2); font-weight: var(--w-bold); line-height: var(--lh-tight); }
.fstretch__sub { color: var(--text-caption); font-family: var(--font-mono); font-size: var(--fs-cell); }
.fstretch__fig { font-family: var(--font-mono); font-size: var(--fs-small); font-variant-numeric: tabular-nums; }
.fstretch__bar { display: flex; height: var(--space-8); margin-top: var(--space-2h); border: var(--bw-heavy) solid var(--border-stamped); background: var(--surface-card); }
.fstretch__seg { display: flex; align-items: center; justify-content: center; min-width: 0px; overflow: hidden; font-family: var(--font-mono); font-size: var(--fs-label); font-weight: var(--w-bold); color: var(--text-heading); }
.fstretch__seg:not(:first-child) { border-left: var(--bw-heavy) solid var(--border-stamped); }
.fstretch__seg[data-i="0"] { background: var(--field); color: var(--text-on-ink); }
.fstretch__seg[data-i="1"] { background: var(--field-mint); }
.fstretch__seg[data-i="2"] { background: var(--field-outfield); }
.fstretch__seg[data-i="3"] { background: var(--field-dirt); }
.fstretch__seg[data-i="4"] { background-position-x: ; background-position-y: ; background-size: ; background-repeat: ; background-attachment: ; background-origin: ; background-clip: ; background-color: ; background-image: repeating-linear-gradient(45deg, color-mix(in srgb, var(--ink-0) 40%, transparent) 0 1px, transparent 1px 5px); color: var(--text-on-ink); }
.fstretch__ends { display: flex; justify-content: space-between; margin-top: var(--space-1h); font-family: var(--font-mono); font-size: var(--fs-cell); font-weight: var(--w-bold); }
.fstretch__end--good { color: var(--accent-positive); }
.fstretch__end--bad { color: var(--clay-deep); }
.fstretch__key { margin-top: var(--space-4); }
.fstretch__keyhead { display: flex; justify-content: space-between; margin-bottom: var(--space-1); font-family: var(--font-display); font-size: var(--fs-label); font-weight: var(--w-bold); letter-spacing: var(--ls-label); text-transform: uppercase; }
.fstretch__key .fstretch__seg { flex: 1 1 0px; }
.fform { min-height: calc(var(--space-16) * 6); }
.fform__top { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: var(--space-3h) var(--space-6); margin-bottom: var(--space-4); }
.fform__read { display: flex; flex: 1 1 20rem; flex-wrap: wrap; align-items: baseline; align-content: center; gap: var(--space-1) var(--space-4); min-height: calc(var(--space-16) + var(--space-8)); padding: var(--space-3h) var(--space-4); border: var(--bw-heavy) solid var(--border-stamped); background: var(--field-wash); }
.fform__big { color: var(--text-heading); font-family: var(--font-display); font-size: var(--fs-hero-2xl); font-weight: var(--w-bold); line-height: var(--lh-solid); }
.fform__lines { display: flex; flex-direction: column; gap: var(--space-1); min-width: 0px; font-family: var(--font-mono); font-size: var(--fs-cell); }
.fform__line1 { color: var(--text-heading); font-weight: var(--w-bold); }
.fform__line2 { color: var(--text-muted); }
.fform__controls { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); }
.fform__windows { display: flex; gap: var(--space-2); }
.fform__legend { display: flex; flex-wrap: wrap; gap: var(--space-2) var(--space-5); margin: var(--space-4) 0 0; padding: 0px; color: var(--text-caption); font-family: var(--font-mono); font-size: var(--fs-cell); line-height: var(--lh-loose); list-style: none; }
.fform__legend b { font-family: var(--font-mono); color: var(--text-heading); }
.fform__note { margin: var(--space-3) 0 0; color: var(--text-caption); font-family: var(--font-mono); font-size: var(--fs-cell); line-height: var(--lh-loose); }
@media (hover: hover) {
.logtable__grid tbody tr:not(.logtable__div, :has(a, button)):hover { background: var(--surface-row-hover); }
}
